  // ---- deliveries -------------------------------------------------------
  interface PendingDelivery {
    inningsId: number;
    overNumber: number;
    position: number;
    sequence: number;
    ballNumber: string;
    delivery: Delivery;
  }

  let deliveryCount = 0;

  for (const [ordinal, innings] of inningsList.entries()) {
    const inningsId = inningsIdByOrdinal.get(ordinal);
    if (inningsId === undefined) continue;

    const pending: PendingDelivery[] = [];
    let sequence = 0;

    for (const over of innings.overs ?? []) {
      let legalBalls = 0;

      for (const [position, delivery] of (over.deliveries as Delivery[]).entries()) {
        sequence += 1;
        const extras = delivery.extras ?? {};

        // The printed ball number counts legal deliveries only. Wides and
        // no-balls do not advance it, so it repeats within an over. It is a
        // label, never an identifier.
        const isLegal = extras.wides === undefined && extras.noballs === undefined;
        if (isLegal) legalBalls += 1;

        pending.push({
          inningsId,
          overNumber: over.over,
          position,
          sequence,
          ballNumber: `${over.over}.${Math.max(legalBalls, 1)}`,
          delivery,
        });
      }
    }

    if (pending.length === 0) continue;

    const deliveryValues = pending.flatMap((item) => {
      const extras = item.delivery.extras ?? {};
      return [
        item.inningsId,
        item.overNumber,
        item.position,
        item.sequence,
        item.ballNumber,
        requirePerson(item.delivery.batter, 'batter'),
        requirePerson(item.delivery.non_striker, 'non-striker'),
        requirePerson(item.delivery.bowler, 'bowler'),
        item.delivery.runs.batter,
        item.delivery.runs.extras,
        item.delivery.runs.total,
        Boolean(item.delivery.runs.non_boundary),
        extras.wides ?? null,
        extras.noballs ?? null,
        extras.byes ?? null,
        extras.legbyes ?? null,
        extras.penalty ?? null,
        submissionId,
      ];
    });

    // The natural key is returned alongside the identifier because the conflict
    // clause may skip rows, so the returned set cannot be matched to the input
    // by position.
    const insertedDeliveries = await client.query(
      `INSERT INTO delivery (
          innings_id, over_number, position_in_over, innings_sequence,
          ball_number, striker_id, non_striker_id, bowler_id,
          runs_off_bat, runs_extras, runs_total, non_boundary,
          extra_wides, extra_noballs, extra_byes, extra_legbyes, extra_penalty,
          submission_id)
       VALUES ${placeholders(pending.length, 18)}
       ON CONFLICT (innings_id, over_number, position_in_over)
         WHERE superseded_at IS NULL
       DO NOTHING
       RETURNING delivery_id, over_number, position_in_over`,
      deliveryValues,
    );

    deliveryCount += insertedDeliveries.rows.length;

    const deliveryIdByKey = new Map<string, number>();
    for (const row of insertedDeliveries.rows) {
      deliveryIdByKey.set(`${row.over_number}:${row.position_in_over}`, row.delivery_id as number);
    }

    // Only deliveries actually inserted receive dependent rows. A delivery that
    // was already present is skipped entirely, as it was one row at a time.
    const inserted = pending.flatMap((item) => {
      const deliveryId = deliveryIdByKey.get(`${item.overNumber}:${item.position}`);
      return deliveryId === undefined ? [] : [{ ...item, deliveryId }];
    });

    const wicketRows = inserted.flatMap((item) =>
      (item.delivery.wickets ?? []).map((wicket, wicketOrdinal) => ({
        deliveryId: item.deliveryId,
        ordinal: wicketOrdinal,
        wicket,
      })),
    );

    if (wicketRows.length > 0) {
      const insertedWickets = await client.query(
        `INSERT INTO delivery_wicket
           (delivery_id, ordinal, kind, source_kind, player_out_id)
         VALUES ${placeholders(wicketRows.length, 5)}
         RETURNING wicket_id, delivery_id, ordinal`,
        wicketRows.flatMap((row) => [
          row.deliveryId,
          row.ordinal,
          row.wicket.kind,
          row.wicket.kind,
     responsible. That name is deliberately not stored: it is attribution for an
     officiating error that nothing in the platform derives from, and officials
     carry no stable identifier by which it could be resolved reliably.';
    

-- ---------------------------------------------------------------------------
-- Deliveries
-- ---------------------------------------------------------------------------

CREATE TABLE delivery (
    delivery_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    innings_id       bigint   NOT NULL REFERENCES innings ON DELETE CASCADE,
    over_number      smallint NOT NULL,
    position_in_over smallint NOT NULL,
    innings_sequence int      NOT NULL,
    ball_number      text     NOT NULL,

    striker_id       bigint NOT NULL REFERENCES person,
    non_striker_id   bigint NOT NULL REFERENCES person,
    bowler_id        bigint NOT NULL REFERENCES person,

    runs_off_bat     smallint NOT NULL DEFAULT 0,
    runs_extras      smallint NOT NULL DEFAULT 0,
    runs_total       smallint NOT NULL,
    non_boundary     boolean  NOT NULL DEFAULT false,

    extra_wides      smallint,
    extra_noballs    smallint,
    extra_byes       smallint,
    extra_legbyes    smallint,
    extra_penalty    smallint,

    revision         int NOT NULL DEFAULT 1,
    submission_id    bigint NOT NULL REFERENCES submission,
    recorded_at      timestamptz NOT NULL DEFAULT now(),
    superseded_at    timestamptz,
    superseded_by    bigint REFERENCES delivery (delivery_id),

    CONSTRAINT delivery_runs_ck    CHECK (runs_total = runs_off_bat + runs_extras),
    CONSTRAINT delivery_striker_ck CHECK (striker_id <> non_striker_id),
    CONSTRAINT delivery_supersede_ck
        CHECK ((superseded_at IS NULL) = (superseded_by IS NULL))
);

COMMENT ON COLUMN delivery.position_in_over IS
    'Zero-based index within the source array. This is the identifying column: the
     printed ball number repeats within an over in 20.4% of overs, and one over
     holds nineteen deliveries of which six share the number 5.1.';

COMMENT ON COLUMN delivery.ball_number IS
    'Display only. Never unique, and never used to join.';

COMMENT ON COLUMN delivery.innings_sequence IS
    'Assigned at ingestion, not derived on read. A correction inherits the
     sequence of the revision it supersedes, so that the order of an innings does
     not shift beneath a consumer paging through it.';

-- Exactly one live row per natural key. Superseded revisions are exempt.
CREATE UNIQUE INDEX delivery_natural_key_live
    ON delivery (innings_id, over_number, position_in_over)
    WHERE superseded_at IS NULL;

CREATE UNIQUE INDEX delivery_sequence_live
    ON delivery (innings_id, innings_sequence)
    WHERE superseded_at IS NULL;

CREATE VIEW delivery_current AS
    SELECT * FROM delivery WHERE superseded_at IS NULL;

COMMENT ON VIEW delivery_current IS
    'The live state of every delivery. All derivation reads this view; correction
     history is available from the base table.';

CREATE TABLE delivery_wicket (
    wicket_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    delivery_id   bigint   NOT NULL REFERENCES delivery ON DELETE CASCADE,
    ordinal       smallint NOT NULL DEFAULT 0,
    kind          text     NOT NULL REFERENCES dismissal_kind (code),
    source_kind   text     NOT NULL,
    player_out_id bigint   NOT NULL REFERENCES person,

