-- ---------------------------------------------------------------------------
-- Innings
-- ---------------------------------------------------------------------------

CREATE TABLE innings (
    innings_id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    fixture_id      bigint   NOT NULL REFERENCES fixture ON DELETE CASCADE,
    ordinal         smallint NOT NULL,
    batting_team_id bigint   NOT NULL REFERENCES team,
    is_super_over   boolean  NOT NULL DEFAULT false,
    declared        boolean  NOT NULL DEFAULT false,
    forfeited       boolean  NOT NULL DEFAULT false,
    target_runs     int,
    target_overs    numeric(4,1),
    penalty_pre     int,
    penalty_post    int,
    UNIQUE (fixture_id, ordinal)
);

COMMENT ON COLUMN innings.ordinal IS
    'Zero-based, matching the source order. Not constrained to two values: 99
     matches carry four innings, the last two being a super over.';

COMMENT ON COLUMN innings.penalty_pre IS
    'Penalty runs belong to the innings and to no delivery. A team total cannot be
     derived from delivery rows alone.';

CREATE TABLE innings_powerplay (
    innings_id bigint       NOT NULL REFERENCES innings ON DELETE CASCADE,
    from_ball  numeric(5,2) NOT NULL,
    to_ball    numeric(5,2) NOT NULL,
    type       text         NOT NULL,
    PRIMARY KEY (innings_id, from_ball, type)
);

CREATE TABLE innings_absent (
    innings_id bigint NOT NULL REFERENCES innings ON DELETE CASCADE,
    person_id  bigint NOT NULL REFERENCES person,
    reason     text   NOT NULL DEFAULT 'absent_hurt',
    PRIMARY KEY (innings_id, person_id)
);

CREATE TABLE innings_miscounted_over (
    innings_id  bigint   NOT NULL REFERENCES innings ON DELETE CASCADE,
    over_number smallint NOT NULL,
    }
  }

  const powerplayRows: unknown[][] = [];
  const absentRows: unknown[][] = [];
  const miscountedRows: unknown[][] = [];

  for (const [ordinal, innings] of inningsList.entries()) {
    const inningsId = inningsIdByOrdinal.get(ordinal);
    if (inningsId === undefined) continue;

    for (const powerplay of innings.powerplays ?? []) {
      powerplayRows.push([inningsId, powerplay.from, powerplay.to, powerplay.type]);
    }

    for (const name of innings.absent_hurt ?? []) {
      const person = personId.get(name);
      if (person !== undefined) {
        absentRows.push([inningsId, person]);
      }
    }

    // The source supplies the ball count as a string in some matches and an
    // integer in others; coerce it.
    for (const [over, detail] of Object.entries(innings.miscounted_overs ?? {})) {
      miscountedRows.push([
        inningsId,
        Number(over),
        Number((detail as { balls: string | number }).balls),
      ]);
    }
  }

  if (powerplayRows.length > 0) {
    await client.query(
      `INSERT INTO innings_powerplay (innings_id, from_ball, to_ball, type)
       VALUES ${placeholders(powerplayRows.length, 4)}
       ON CONFLICT DO NOTHING`,
      powerplayRows.flat(),
    );
  }

  if (absentRows.length > 0) {
    await client.query(
      `INSERT INTO innings_absent (innings_id, person_id)
       VALUES ${placeholders(absentRows.length, 2)}
       ON CONFLICT DO NOTHING`,
      absentRows.flat(),
    );
  }
